$$;

create or replace function attachment_target_exists(
  p_site uuid,
  p_entity_type text,
  p_entity_id uuid
) returns boolean
language sql stable security definer set search_path = public as $$
  select case p_entity_type
    when 'obligation_task' then exists (
      select 1 from obligation_tasks where id = p_entity_id and site_id = p_site
    )
    when 'action_before' then exists (
      select 1 from actions where id = p_entity_id and site_id = p_site
    )
    when 'action_after' then exists (
      select 1 from actions where id = p_entity_id and site_id = p_site
    )
    when 'permit' then exists (
      select 1 from site_permits where id = p_entity_id and site_id = p_site
    )
    when 'inspection' then exists (
      select 1 from inspections where id = p_entity_id and site_id = p_site
    )
    when 'finding' then exists (
      select 1 from findings where id = p_entity_id and site_id = p_site
    )
    when 'incident' then exists (
      select 1 from incidents where id = p_entity_id and site_id = p_site
    )
    when 'era_assessment' then exists (
      select 1 from era_assessments where id = p_entity_id and site_id = p_site
    )
    else false
  end
$$;

create or replace function attachment_evidence_is_valid(
  p_site uuid,
  p_entity_type text,
  p_entity_id uuid,
  p_storage_path text
) returns boolean
language plpgsql stable security definer set search_path = public, storage as $$
begin
  if not evidence_path_is_valid(p_storage_path) then
    return false;
  end if;

  return split_part(p_storage_path, '/', 1)::uuid = p_site
    and split_part(p_storage_path, '/', 2) = p_entity_type
    and split_part(split_part(p_storage_path, '/', 3), '.', 1)::uuid = p_entity_id
    and attachment_target_exists(p_site, p_entity_type, p_entity_id)
    and exists (
      select 1
      from storage.objects object
      where object.bucket_id = 'evidence'
        and object.name = p_storage_path
    );
end
$$;

