create or replace function assign_action(p_id uuid, p_owner uuid, p_owner_name text) returns void
language plpgsql security definer set search_path = public as $$
declare
  v actions;
  v_owner_name text;
begin
  select * into v from actions where id = p_id for update;

  if not found then
    raise exception 'Action % does not exist.', p_id using errcode = 'P0002';
  end if;

  if not has_site_role(v.site_id, array['plant_manager', 'dept_head']::app_role[]) then
    raise exception '공장장 또는 실무부서장만 조치를 배정할 수 있습니다.';
  end if;

  if v.status not in ('open', 'returned') then
    raise exception 'open 또는 returned 상태의 조치만 배정할 수 있습니다.';
  end if;

  select profile.name
  into v_owner_name
  from profiles profile
  where profile.id = p_owner
    and profile.active
    and exists (
      select 1
      from role_assignments assignment
      where assignment.user_id = profile.id
        and assignment.role in ('env_officer', 'plant_manager')
        and assignment.scope = 'site'
        and assignment.site_id = v.site_id
    );

  if v_owner_name is null then
    raise exception '조치 담당자는 해당 사업장의 환경기술인 또는 공장장이어야 합니다.';
  end if;

  if p_owner_name is distinct from v_owner_name then
    raise exception '조치 담당자 이름이 사용자 프로필과 일치하지 않습니다.';
  end if;

  update actions
  set owner_id = p_owner,
      owner_name = v_owner_name,
      status = 'open',
      done_at = null,
      done_by = null,
      confirmed_by = null,
      confirmed_at = null,
      closed_by = null,
      closed_at = null,
      return_reason = null
  where id = p_id;
end $$;
create or replace function evidence_path_is_valid(p_name text) returns boolean
language sql immutable as $$
  select p_name ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/(obligation_task|action_before|action_after|permit|inspection|finding|incident|era_assessment)/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.[a-z0-9]{1,16}$'
$$;

create or replace function attachment_target_exists(
  p_site uuid,
  p_entity_type text,
  p_entity_id uuid
) returns boolean
language sql stable security definer set search_path = public as $$
  select case p_entity_type
    when 'obligation_task' then exists (
      select 1 from obligation_tasks where id = p_entity_id and site_id = p_site
    )
    when 'action_before' then exists (
      select 1 from actions where id = p_entity_id and site_id = p_site
    )
    when 'action_after' then exists (
      select 1 from actions where id = p_entity_id and site_id = p_site
    )
    when 'permit' then exists (
      select 1 from site_permits where id = p_entity_id and site_id = p_site
    )
    when 'inspection' then exists (
      select 1 from inspections where id = p_entity_id and site_id = p_site
    )
    when 'finding' then exists (
      select 1 from findings where id = p_entity_id and site_id = p_site
    )
    when 'incident' then exists (
      select 1 from incidents where id = p_entity_id and site_id = p_site
    )
    when 'era_assessment' then exists (
      select 1 from era_assessments where id = p_entity_id and site_id = p_site
    )
    else false
  end
$$;

create or replace function attachment_evidence_is_valid(
  p_site uuid,
  p_entity_type text,
  p_entity_id uuid,
  p_storage_path text
) returns boolean
language plpgsql stable security definer set search_path = public, storage as $$
begin
  if not evidence_path_is_valid(p_storage_path) then
    return false;
  end if;

  return split_part(p_storage_path, '/', 1)::uuid = p_site
    and split_part(p_storage_path, '/', 2) = p_entity_type
    and split_part(split_part(p_storage_path, '/', 3), '.', 1)::uuid = p_entity_id
    and attachment_target_exists(p_site, p_entity_type, p_entity_id)
    and exists (
      select 1
      from storage.objects object
      where object.bucket_id = 'evidence'
        and object.name = p_storage_path
    );
end
$$;

create or replace function can_read_evidence_object(p_name text) returns boolean
language plpgsql stable security definer set search_path = public as $$
begin
  if not evidence_path_is_valid(p_name) then
    return false;
  end if;
  return can_read_site(split_part(p_name, '/', 1)::uuid);
end $$;

create or replace function guard_attachment_evidence() returns trigger
language plpgsql as $$
begin
  if not attachment_evidence_is_valid(new.site_id, new.entity_type, new.entity_id, new.storage_path) then
