  if has_site_role(p_site, array['env_officer', 'plant_manager']::app_role[]) then
    return attachment_evidence_is_valid(
      p_site,
      p_entity_type,
      p_entity_id,
      p_storage_path
    );
  end if;

  if p_entity_type = 'inspection'
