1: create or replace function public.my_site_ids() returns setof uuid
2: language sql stable security definer set search_path = public as $$
3:   select site.id
4:   from profiles profile
5:   join role_assignments assignment on assignment.user_id = profile.id
6:   join sites site on assignment.scope = 'company'
7:     or (assignment.scope = 'division' and assignment.division_code = site.division_code)
8:     or (assignment.scope = 'site' and assignment.site_id = site.id)
9:   where profile.id = auth.uid()
10:     and profile.active
11: $$;
