19: language sql stable security definer set search_path = public as $$
20:   select exists (
21:     select 1
22:     from profiles profile
23:     join role_assignments assignment on assignment.user_id = profile.id
24:     join sites site on site.id = p_site
25:     where profile.id = auth.uid()
26:       and profile.active
27:       and assignment.role = any(p_roles)
