create or replace function public.guard_profile_security_fields() returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if current_user <> 'authenticated' then
    return new;
  end if;

  if public.has_role(array['she_staff']::public.app_role[]) then
    return new;
  end if;

  if old.id is distinct from auth.uid()
     or new.id is distinct from old.id
     or new.email is distinct from old.email
     or new.active is distinct from old.active
     or new.created_at is distinct from old.created_at then
    raise exception using
      errcode = '42501',
      message = '프로필 보안 필드는 활성 SHE팀 관리자만 변경할 수 있습니다.';
  end if;

  return new;
end;
$$;

revoke all on function public.guard_profile_security_fields() from public, anon, authenticated;

create trigger profiles_security_fields_guard
before update on public.profiles
for each row execute function public.guard_profile_security_fields();

