56:     raise exception '가져오기 요청은 JSON 객체여야 합니다.';
57:   end if;
58: 
59:   select array_agg(key order by key) into v_keys from jsonb_object_keys(p_envelope) key;
60:   if v_keys is distinct from array['rows', 'source_name', 'source_sha256']::text[] then
61:     raise exception '가져오기 요청 필드가 계약과 일치하지 않습니다.';
62:   end if;
63: 
64:   if jsonb_typeof(p_envelope -> 'source_name') is distinct from 'string'
65:      or btrim(p_envelope ->> 'source_name') = ''
66:      or length(p_envelope ->> 'source_name') > 255 then
67:     raise exception 'source_name은 1자 이상 255자 이하 문자열이어야 합니다.';
