70:      or (p_envelope ->> 'source_sha256') !~ '^[0-9a-f]{64}$' then
71:     raise exception 'source_sha256은 소문자 64자리 SHA-256이어야 합니다.';
72:   end if;
73:   if jsonb_typeof(p_envelope -> 'rows') is distinct from 'array'
74:      or jsonb_array_length(p_envelope -> 'rows') = 0 then
75:     raise exception 'rows는 한 행 이상의 JSON 배열이어야 합니다.';
76:   end if;
