80:   v_rows := p_envelope -> 'rows';
81:   v_payload_fingerprint := encode(extensions.digest(v_rows::text, 'sha256'), 'hex');
82: 
83:   perform pg_advisory_xact_lock(hashtextextended('permit_updates:' || v_source_sha256, 0));
84:   select * into v_existing
85:   from import_batches
