112:        or jsonb_typeof(v_row -> 'permit_type') is distinct from 'string'
113:        or jsonb_typeof(v_row -> 'applicable') is distinct from 'boolean'
114:        or jsonb_typeof(v_row -> 'status') is distinct from 'string' then
115:       raise exception '데이터 %행의 필수 값 형식이 올바르지 않습니다.', v_row_number;
116:     end if;
117: 
118:     if (v_row ->> 'permit_type') not in (select unnest(enum_range(null::permit_type))::text)
119:        or (v_row ->> 'status') not in (select unnest(enum_range(null::permit_status))::text) then
120:       raise exception '데이터 %행의 인허가 유형 또는 상태가 허용되지 않습니다.', v_row_number;
121:     end if;
122: 
123:     if exists (
124:       select 1
125:       from unnest(array['grade', 'detail', 'permit_no', 'authority', 'conditions']) field
126:       where jsonb_typeof(v_row -> field) not in ('string', 'null')
127:     ) then
128:       raise exception '데이터 %행의 선택 문자열 형식이 올바르지 않습니다.', v_row_number;
129:     end if;
130:     if exists (
131:       select 1
132:       from unnest(array['grade', 'detail', 'permit_no', 'authority', 'conditions']) field
133:       where jsonb_typeof(v_row -> field) = 'string' and btrim(v_row ->> field) = ''
134:     ) then
135:       raise exception '데이터 %행의 선택 문자열은 비어 있거나 공백만 포함할 수 없습니다.', v_row_number;
136:     end if;
137: 
138:     if jsonb_typeof(v_row -> 'items') is distinct from 'array'
139:        or exists (
140:          select 1 from jsonb_array_elements(v_row -> 'items') item
141:          where jsonb_typeof(item) is distinct from 'string' or btrim(item #>> '{}') = ''
142:        ) then
143:       raise exception '데이터 %행의 대상 항목은 빈 값이 없는 문자열 배열이어야 합니다.', v_row_number;
144:     end if;
145: 
146:     if jsonb_typeof(v_row -> 'quantity') not in ('number', 'null')
147:        or (
148:          jsonb_typeof(v_row -> 'quantity') = 'number'
149:          and (
150:            (v_row ->> 'quantity') !~ '^-?(0|[1-9][0-9]*)$'
151:            or (v_row ->> 'quantity')::numeric not between -2147483648 and 2147483647
152:          )
153:        ) then
154:       raise exception '데이터 %행의 수량은 32비트 정수 또는 null이어야 합니다.', v_row_number;
155:     end if;
156: 
157:     if jsonb_typeof(v_row -> 'issued_on') not in ('string', 'null') then
158:       raise exception '데이터 %행의 발급일은 유효한 YYYY-MM-DD 또는 null이어야 합니다.', v_row_number;
159:     end if;
160:     if jsonb_typeof(v_row -> 'issued_on') = 'string' then
161:       if (v_row ->> 'issued_on') !~ '^\d{4}-\d{2}-\d{2}$' then
162:         raise exception '데이터 %행의 발급일은 유효한 YYYY-MM-DD 또는 null이어야 합니다.', v_row_number;
163:       end if;
164:       begin
165:         perform (v_row ->> 'issued_on')::date;
166:       exception
167:         when datetime_field_overflow or invalid_datetime_format then
168:           raise exception '데이터 %행의 발급일은 유효한 YYYY-MM-DD 또는 null이어야 합니다.', v_row_number;
169:       end;
170:     end if;
171: 
172:     v_key := (v_row ->> 'site_code') || chr(31) || (v_row ->> 'permit_type');
173:     if v_seen ? v_key then
174:       raise exception '데이터 %행의 사업장·인허가 유형이 중복되었습니다.', v_row_number;
175:     end if;
176:     v_seen := v_seen || jsonb_build_object(v_key, true);
177: 
178:     if not exists (select 1 from sites where code = v_row ->> 'site_code') then
179:       raise exception '데이터 %행의 사업장 코드가 등록되지 않았습니다.', v_row_number;
180:     end if;
181:     if not exists (
182:       select 1
183:       from site_permits permit
184:       join sites site on site.id = permit.site_id
185:       where site.code = v_row ->> 'site_code'
186:         and permit.permit_type::text = v_row ->> 'permit_type'
187:     ) then
188:       raise exception '데이터 %행의 인허가 대상이 존재하지 않습니다.', v_row_number;
189:     end if;
190:   end loop;
191: 
192:   for v_row in select value from jsonb_array_elements(v_rows)
193:   loop
194:     update site_permits permit
195:     set applicable = (v_row ->> 'applicable')::boolean,
196:         grade = case when jsonb_typeof(v_row -> 'grade') = 'string' then v_row ->> 'grade' else permit.grade end,
197:         detail = case when jsonb_typeof(v_row -> 'detail') = 'string' then v_row ->> 'detail' else permit.detail end,
198:         items = case
199:           when jsonb_array_length(v_row -> 'items') > 0
200:             then array(select item #>> '{}' from jsonb_array_elements(v_row -> 'items') item)
201:           else permit.items
202:         end,
203:         quantity = case when jsonb_typeof(v_row -> 'quantity') = 'number' then (v_row ->> 'quantity')::int else permit.quantity end,
204:         permit_no = case when jsonb_typeof(v_row -> 'permit_no') = 'string' then v_row ->> 'permit_no' else permit.permit_no end,
205:         authority = case when jsonb_typeof(v_row -> 'authority') = 'string' then v_row ->> 'authority' else permit.authority end,
206:         issued_on = case when jsonb_typeof(v_row -> 'issued_on') = 'string' then (v_row ->> 'issued_on')::date else permit.issued_on end,
207:         conditions = case when jsonb_typeof(v_row -> 'conditions') = 'string' then v_row ->> 'conditions' else permit.conditions end,
208:         status = (v_row ->> 'status')::permit_status,
209:         source = 'import:' || v_source_name || ':' || v_source_sha256,
210:         updated_by = v_actor,
211:         updated_at = now()
212:     from sites site
213:     where site.id = permit.site_id
214:       and site.code = v_row ->> 'site_code'
215:       and permit.permit_type::text = v_row ->> 'permit_type';
216:   end loop;
217: 
218:   insert into import_batches (
219:     kind, source_name, source_sha256, payload_fingerprint, status,
220:     row_count, actor, completed_at, error_summary
221:   ) values (
222:     'permit_updates', v_source_name, v_source_sha256, v_payload_fingerprint, 'completed',
223:     jsonb_array_length(v_rows), v_actor, now(), null
224:   ) returning id into v_batch_id;
225: 
226:   return v_batch_id;
227: end
228: $$;
