230: revoke all on function admin_import_permit_updates(jsonb) from public;
231: revoke all on function admin_import_permit_updates(jsonb) from anon;
232: grant execute on function admin_import_permit_updates(jsonb) to authenticated;
1: create type permit_document_status as enum (
2:   'pending_review',
3:   'confirmed',
4:   'rejected',
5:   'failed'
6: );
