19: create table permit_documents (
20:   id                    uuid primary key default gen_random_uuid(),
21:   source_sha256         text not null unique
22:     check (source_sha256 ~ '^[0-9a-f]{64}$'),
23:   original_filename     text not null check (btrim(original_filename) <> ''),
24:   detected_mime         text not null
25:     check (detected_mime in ('application/pdf', 'image/jpeg', 'image/png')),
26:   size_bytes            bigint not null check (size_bytes > 0),
27:   page_count            int not null check (page_count > 0),
28:   site_id_candidate     uuid references sites(id),
29:   permit_type_candidate permit_type,
30:   extracted_text        text,
31:   field_candidates      jsonb not null default '{}'::jsonb
32:     check (jsonb_typeof(field_candidates) = 'object'),
33:   extraction_method     permit_document_extraction_method not null,
34:   error_code            text,
35:   error_message         text,
36:   reviewer_id           uuid references profiles(id),
37:   reviewed_at           timestamptz,
38:   rejection_reason      text,
39:   review_bucket         text not null default 'permit-documents'
40:     check (review_bucket = 'permit-documents'),
41:   review_storage_path   text not null check (btrim(review_storage_path) <> ''),
42:   evidence_storage_path text,
43:   status                permit_document_status not null default 'pending_review',
44:   created_at            timestamptz not null default now(),
45:   updated_at            timestamptz not null default now(),
46:   unique (review_bucket, review_storage_path),
47:   constraint permit_documents_status_fields check (
48:     (
49:       status = 'pending_review'
50:       and reviewer_id is null
51:       and reviewed_at is null
52:       and rejection_reason is null
53:       and evidence_storage_path is null
54:       and error_code is null
55:       and error_message is null
56:     )
57:     or (
58:       status = 'confirmed'
59:       and reviewer_id is not null
60:       and reviewed_at is not null
61:       and site_id_candidate is not null
62:       and permit_type_candidate is not null
63:       and evidence_storage_path is not null
64:       and btrim(evidence_storage_path) <> ''
65:       and rejection_reason is null
66:       and error_code is null
67:       and error_message is null
68:     )
69:     or (
70:       status = 'rejected'
71:       and reviewer_id is not null
72:       and reviewed_at is not null
73:       and rejection_reason is not null
74:       and btrim(rejection_reason) <> ''
75:       and evidence_storage_path is null
76:       and error_code is null
77:       and error_message is null
78:     )
79:     or (
80:       status = 'failed'
81:       and reviewer_id is null
82:       and reviewed_at is null
83:       and rejection_reason is null
84:       and evidence_storage_path is null
85:       and error_code is not null
86:       and error_message is not null
87:       and btrim(error_code) <> ''
88:       and btrim(error_message) <> ''
89:     )
90:   )
