108: create or replace function confirm_permit_document(
109:   p_document uuid,
110:   p_reviewed jsonb
111: ) returns uuid
112: language plpgsql
113: security definer
114: set search_path = public, pg_temp
115: as $$
116: declare
117:   v_actor uuid := auth.uid();
118:   v_document permit_documents%rowtype;
119:   v_keys text[];
120:   v_site_id uuid;
121:   v_permit_type permit_type;
122:   v_applicable boolean;
123:   v_grade text;
124:   v_detail text;
125:   v_items text[];
126:   v_quantity int;
127:   v_permit_no text;
128:   v_authority text;
129:   v_issued_on date;
130:   v_conditions text;
131:   v_status permit_status;
132:   v_evidence_path text;
133:   v_path_permit_id uuid;
134:   v_existing site_permits%rowtype;
135:   v_permit_id uuid;
136:   v_attachment attachments%rowtype;
137: begin
138:   if v_actor is null or not exists (
139:     select 1
140:     from profiles profile
141:     join role_assignments assignment on assignment.user_id = profile.id
142:     where profile.id = v_actor
143:       and profile.active
144:       and assignment.role = 'she_staff'
145:       and assignment.scope = 'company'
146:   ) then
147:     raise exception '활성 SHE팀 담당자만 인허가 문서를 확정할 수 있습니다.' using errcode = '42501';
148:   end if;
149: 
150:   select * into v_document
151:   from permit_documents
152:   where id = p_document
153:   for update;
154: 
155:   if not found then
156:     raise exception '검토할 인허가 문서를 찾을 수 없습니다.';
157:   end if;
158:   if v_document.status <> 'pending_review' then
159:     raise exception '대기 중인 인허가 문서만 확정할 수 있습니다.';
160:   end if;
161:   if jsonb_typeof(p_reviewed) is distinct from 'object' then
162:     raise exception '확정 값은 JSON 객체여야 합니다.';
163:   end if;
164: 
165:   select array_agg(key order by key) into v_keys from jsonb_object_keys(p_reviewed) key;
166:   if v_keys is distinct from array[
167:     'applicable', 'authority', 'conditions', 'detail', 'evidence_storage_path',
168:     'grade', 'issued_on', 'items', 'permit_no', 'permit_type', 'quantity',
169:     'site_id', 'status'
170:   ]::text[] then
171:     raise exception '확정 값의 필드가 계약과 일치하지 않습니다.';
172:   end if;
173: 
174:   if jsonb_typeof(p_reviewed -> 'site_id') is distinct from 'string'
175:      or (p_reviewed ->> 'site_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
176:     raise exception 'site_id는 유효한 UUID여야 합니다.';
177:   end if;
178:   v_site_id := (p_reviewed ->> 'site_id')::uuid;
179:   if not exists (select 1 from sites where id = v_site_id) then
180:     raise exception '확정 대상 사업장을 찾을 수 없습니다.';
181:   end if;
182:   if v_document.site_id_candidate is not null
183:      and v_document.site_id_candidate <> v_site_id then
184:     raise exception '확정 사업장이 문서 후보와 충돌합니다.';
185:   end if;
186: 
187:   if jsonb_typeof(p_reviewed -> 'permit_type') is distinct from 'string'
188:      or (p_reviewed ->> 'permit_type') not in (
189:        select unnest(enum_range(null::permit_type))::text
190:      ) then
191:     raise exception 'permit_type이 유효하지 않습니다.';
192:   end if;
193:   v_permit_type := (p_reviewed ->> 'permit_type')::permit_type;
194:   if v_document.permit_type_candidate is not null
195:      and v_document.permit_type_candidate <> v_permit_type then
196:     raise exception '확정 인허가 유형이 문서 후보와 충돌합니다.';
197:   end if;
198: 
199:   if jsonb_typeof(p_reviewed -> 'applicable') is distinct from 'boolean' then
200:     raise exception 'applicable은 boolean이어야 합니다.';
201:   end if;
202:   v_applicable := (p_reviewed ->> 'applicable')::boolean;
203: 
204:   if coalesce(jsonb_typeof(p_reviewed -> 'grade'), 'null') not in ('null', 'string')
205:      or coalesce(jsonb_typeof(p_reviewed -> 'detail'), 'null') not in ('null', 'string')
206:      or coalesce(jsonb_typeof(p_reviewed -> 'permit_no'), 'null') not in ('null', 'string')
207:      or coalesce(jsonb_typeof(p_reviewed -> 'authority'), 'null') not in ('null', 'string')
208:      or coalesce(jsonb_typeof(p_reviewed -> 'conditions'), 'null') not in ('null', 'string') then
209:     raise exception '선택 문자열 필드의 형식이 유효하지 않습니다.';
210:   end if;
211:   if exists (
212:     select 1
213:     from jsonb_each(p_reviewed) entry
214:     where entry.key in ('grade', 'detail', 'permit_no', 'authority', 'conditions')
215:       and jsonb_typeof(entry.value) = 'string'
216:       and btrim(entry.value #>> '{}') = ''
217:   ) then
218:     raise exception '선택 문자열 필드에 공백 값은 허용되지 않습니다.';
219:   end if;
220:   v_grade := p_reviewed ->> 'grade';
221:   v_detail := p_reviewed ->> 'detail';
222:   v_permit_no := p_reviewed ->> 'permit_no';
223:   v_authority := p_reviewed ->> 'authority';
224:   v_conditions := p_reviewed ->> 'conditions';
225: 
226:   if jsonb_typeof(p_reviewed -> 'items') is distinct from 'array'
227:      or exists (
228:        select 1 from jsonb_array_elements(p_reviewed -> 'items') item
229:        where jsonb_typeof(item) <> 'string' or btrim(item #>> '{}') = ''
230:      ) then
231:     raise exception 'items는 공백이 없는 문자열 배열이어야 합니다.';
232:   end if;
233:   select coalesce(array_agg(item.value order by item.ordinality), '{}'::text[])
234:   into v_items
235:   from jsonb_array_elements_text(p_reviewed -> 'items') with ordinality item(value, ordinality);
236: 
237:   if coalesce(jsonb_typeof(p_reviewed -> 'quantity'), 'null') not in ('null', 'number')
238:      or (
239:        jsonb_typeof(p_reviewed -> 'quantity') = 'number'
240:        and (
241:          (p_reviewed ->> 'quantity')::numeric <> trunc((p_reviewed ->> 'quantity')::numeric)
242:          or (p_reviewed ->> 'quantity')::numeric < -2147483648
243:          or (p_reviewed ->> 'quantity')::numeric > 2147483647
244:        )
245:      ) then
246:     raise exception 'quantity는 32비트 정수 또는 null이어야 합니다.';
247:   end if;
248:   v_quantity := (p_reviewed ->> 'quantity')::int;
249: 
250:   if coalesce(jsonb_typeof(p_reviewed -> 'issued_on'), 'null') not in ('null', 'string')
251:      or (
252:        jsonb_typeof(p_reviewed -> 'issued_on') = 'string'
253:        and (p_reviewed ->> 'issued_on') !~ '^\d{4}-\d{2}-\d{2}$'
254:      ) then
255:     raise exception 'issued_on은 YYYY-MM-DD 날짜 또는 null이어야 합니다.';
256:   end if;
257:   if jsonb_typeof(p_reviewed -> 'issued_on') = 'string' then
258:     begin
259:       v_issued_on := (p_reviewed ->> 'issued_on')::date;
260:     exception when datetime_field_overflow then
261:       raise exception 'issued_on은 실제 달력 날짜여야 합니다.';
262:     end;
263:   end if;
264: 
265:   if jsonb_typeof(p_reviewed -> 'status') is distinct from 'string'
266:      or (p_reviewed ->> 'status') not in (
267:        select unnest(enum_range(null::permit_status))::text
268:      ) then
269:     raise exception 'status가 유효하지 않습니다.';
270:   end if;
271:   v_status := (p_reviewed ->> 'status')::permit_status;
272: 
273:   if jsonb_typeof(p_reviewed -> 'evidence_storage_path') is distinct from 'string'
274:      or btrim(p_reviewed ->> 'evidence_storage_path') = '' then
275:     raise exception 'evidence_storage_path가 필요합니다.';
276:   end if;
277:   v_evidence_path := p_reviewed ->> 'evidence_storage_path';
278:   if not evidence_path_is_valid(v_evidence_path)
279:      or split_part(v_evidence_path, '/', 1)::uuid <> v_site_id
280:      or split_part(v_evidence_path, '/', 2) <> 'permit' then
281:     raise exception '확정 증빙 경로가 사업장 인허가 경로 규칙과 일치하지 않습니다.';
282:   end if;
283:   v_path_permit_id := split_part(split_part(v_evidence_path, '/', 3), '.', 1)::uuid;
284: 
285:   select * into v_existing
286:   from site_permits
287:   where site_id = v_site_id and permit_type = v_permit_type
288:   for update;
289: 
290:   if found and v_existing.id <> v_path_permit_id then
291:     raise exception '확정 증빙 경로가 기존 인허가 대상과 충돌합니다.';
292:   end if;
293:   if found and v_existing.issued_on is not null and v_issued_on is not null
294:      and v_issued_on < v_existing.issued_on then
295:     raise exception '기존 인허가보다 오래된 발급일로 확정할 수 없습니다.';
296:   end if;
297: 
298:   insert into site_permits (
299:     id, site_id, permit_type, applicable, grade, detail, items, quantity,
300:     permit_no, authority, issued_on, conditions, status, source, updated_by, updated_at
301:   ) values (
302:     v_path_permit_id, v_site_id, v_permit_type, v_applicable, v_grade, v_detail,
303:     v_items, v_quantity, v_permit_no, v_authority, v_issued_on, v_conditions,
304:     v_status, 'permit_document', v_actor, now()
305:   )
306:   on conflict (site_id, permit_type) do update set
307:     applicable = excluded.applicable,
308:     grade = excluded.grade,
309:     detail = excluded.detail,
310:     items = excluded.items,
311:     quantity = excluded.quantity,
312:     permit_no = excluded.permit_no,
313:     authority = excluded.authority,
314:     issued_on = excluded.issued_on,
315:     conditions = excluded.conditions,
316:     status = excluded.status,
317:     source = excluded.source,
318:     updated_by = excluded.updated_by,
319:     updated_at = excluded.updated_at
320:   returning id into v_permit_id;
321: 
322:   insert into attachments (
323:     id, site_id, entity_type, entity_id, storage_path, file_name, mime,
324:     size_bytes, uploaded_by
325:   ) values (
326:     v_document.id, v_site_id, 'permit', v_permit_id, v_evidence_path,
327:     v_document.original_filename, v_document.detected_mime,
328:     v_document.size_bytes, v_actor
329:   )
330:   on conflict (id) do nothing;
331: 
332:   select * into v_attachment from attachments where id = v_document.id;
333:   if v_attachment.site_id <> v_site_id
334:      or v_attachment.entity_type <> 'permit'
335:      or v_attachment.entity_id <> v_permit_id
336:      or v_attachment.storage_path <> v_evidence_path
337:      or v_attachment.file_name <> v_document.original_filename
338:      or v_attachment.mime is distinct from v_document.detected_mime
339:      or v_attachment.size_bytes is distinct from v_document.size_bytes then
340:     raise exception '문서 첨부 메타데이터가 기존 대상과 충돌합니다.';
341:   end if;
342: 
343:   update permit_documents
344:   set site_id_candidate = v_site_id,
345:       permit_type_candidate = v_permit_type,
346:       evidence_storage_path = v_evidence_path,
347:       status = 'confirmed',
348:       reviewer_id = v_actor,
349:       reviewed_at = now(),
350:       rejection_reason = null,
351:       updated_at = now()
352:   where id = v_document.id;
353: 
354:   return v_permit_id;
355: end
356: $$;
357: 
358: create or replace function reject_permit_document(
359:   p_document uuid,
360:   p_reason text
361: ) returns void
362: language plpgsql
363: security definer
364: set search_path = public, pg_temp
365: as $$
366: declare
367:   v_actor uuid := auth.uid();
368:   v_document permit_documents%rowtype;
369: begin
370:   if v_actor is null or not exists (
371:     select 1
372:     from profiles profile
373:     join role_assignments assignment on assignment.user_id = profile.id
374:     where profile.id = v_actor
375:       and profile.active
376:       and assignment.role = 'she_staff'
377:       and assignment.scope = 'company'
378:   ) then
379:     raise exception '활성 SHE팀 담당자만 인허가 문서를 반려할 수 있습니다.' using errcode = '42501';
380:   end if;
381:   if p_reason is null or btrim(p_reason) = '' then
382:     raise exception '반려 사유를 입력해야 합니다.';
383:   end if;
384: 
385:   select * into v_document
386:   from permit_documents
387:   where id = p_document
388:   for update;
389: 
390:   if not found then
391:     raise exception '검토할 인허가 문서를 찾을 수 없습니다.';
392:   end if;
393:   if v_document.status <> 'pending_review' then
394:     raise exception '대기 중인 인허가 문서만 반려할 수 있습니다.';
395:   end if;
396: 
397:   update permit_documents
398:   set status = 'rejected',
399:       reviewer_id = v_actor,
400:       reviewed_at = now(),
401:       rejection_reason = btrim(p_reason),
402:       updated_at = now()
403:   where id = v_document.id;
404: end
405: $$;
406: 
407: revoke all on function confirm_permit_document(uuid, jsonb) from public, anon;
408: grant execute on function confirm_permit_document(uuid, jsonb) to authenticated;
409: revoke all on function reject_permit_document(uuid, text) from public, anon;
410: grant execute on function reject_permit_document(uuid, text) to authenticated;

